import pandas as pd
train = pd.read_csv('b3_te_zt400_train.csv')
top_train = train.sort_values('target', ascending=False).head(15)

for i, row in top_train.iterrows():
    non_zero = {k:v for k,v in row.items() if k != 'target' and v > 0}
    print(f"Index {i} (target {row['target']:.4f}): {non_zero}")

import pandas as pd
pool = pd.read_csv('b3_te_zt400_pool.csv')
for c in ['c086', 'c063']:
    row = pool[pool['candidate_id'] == c].iloc[0]
    non_zero = {k:v for k,v in row.items() if k != 'candidate_id' and v > 0}
    print(f"{c}: {non_zero}")

import pandas as pd
pool = pd.read_csv('b3_te_zt400_pool.csv')
for c in ['c010', 'c037', 'c049', 'c043', 'c046', 'c054']:
    row = pool[pool['candidate_id'] == c].iloc[0]
    non_zero = {k:v for k,v in row.items() if k != 'candidate_id' and v > 0}
    print(f"{c}: {non_zero}")

import pandas as pd
train = pd.read_csv('b3_te_zt400_train.csv')
features = [c for c in train.columns if c != 'target']
for i, row in train[train['Sn'] > 0.4].iterrows():
    if len(row[features][row[features] > 0]) == 1:
        print(f"Index {i}, Target {row['target']}, Sn {row['Sn']}")

